</code></pre><h3>JavaScript 主题切换</h3><pre><code>class ThemeManager {
  constructor() {
    this.theme = this.getInitialTheme();
    this.init();
  }

  getInitialTheme() {
    const stored = localStorage.getItem('theme');
    if (stored) return stored;

    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    return prefersDark ? 'dark' : 'light';
  }

  init() {
    this.applyTheme(this.theme);
    this.listenForSystemChanges();
  }

  applyTheme(theme) {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('theme', theme);
    this.theme = theme;

    // 更新 meta 主题色
    const metaTheme = document.querySelector('meta[name="theme-color"]');
    const colors = {
      light: '#ffffff',
      dark: '#0f172a'
    };
    metaTheme.content = colors[theme];

    // 触发主题变更事件
    window.dispatchEvent(new CustomEvent('themechange', { detail: { theme } }));
  }

  toggle() {
    const newTheme = this.theme === 'light' ? 'dark' : 'light';
    this.applyTheme(newTheme);
  }

  listenForSystemChanges() {
    window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', (e) => {
      if (!localStorage.getItem('theme')) {
        this.applyTheme(e.matches ? 'dark' : 'light');
      }
    });
  }
}

export const themeManager = new ThemeManager();
</code></pre><h2 id="motion-design">动效与微交互</h2><p>动效设计是现代 UI 的重要组成部分，它不仅能够提供视觉反馈，还能够引导用户注意力、传达状态变化、增强品牌识别。</p><h3>微交互设计</h3><pre><code>/* 按钮点击涟漪效果 */
.ripple-button {
